def check_fact_relation_laws(fact: dict, payload: dict, snapshot: dict, st: store.Store) -> list[str]:
    errors = []
    reg = relation_registry()
    rel = fact["relation"]
    if rel not in reg:
        return [f"FACT_RELATION_UNREGISTERED:{rel}"]
    row = reg[rel]
