            errors.append(f"FACT_ANCHOR_CARDINALITY:{rel} expected 1 got {n}")
    elif law.get("class") == "source-text":
        if n < 1:
            errors.append(f"FACT_ANCHOR_CARDINALITY:{rel} expected >=1 got {n}")
